// Sigle attuali -> sigle accettate dal servizio Variazioni colturali.
// BT: Andria/Barletta/Trani erano in BA, Margherita di Savoia/Trinitapoli/
//     San Ferdinando di Puglia in FG.
// SU: la provincia del Sud Sardegna non esiste nel servizio; i comuni sono
//     distribuiti fra CA, OR, NU e SS.
export const SERVICE_PROVINCE_CANDIDATES = Object.freeze({
  BT: Object.freeze(['BA', 'FG']),
  FC: Object.freeze(['FO']),
  FM: Object.freeze(['AP']),
  MB: Object.freeze(['MI']),
  PU: Object.freeze(['PS']),
  SU: Object.freeze(['CA', 'OR', 'NU', 'SS']),
});

/** Sigla della provincia di un comune catastale (stringa vuota se ignota). */
export function provinceOf(comuneCode) {
  const code = String(comuneCode || '').trim().toUpperCase();
  return COMUNE_PROVINCE[code] || '';
}

/** Sigle da provare presso il servizio per una data provincia attuale. */
export function serviceProvinces(sigla) {
  const key = String(sigla || '').trim().toUpperCase();
  return SERVICE_PROVINCE_CANDIDATES[key] || (key ? [key] : []);
}
